print('--- 0007 urutan dan kemajuan')
EN=f"(select id from enrollments where course_id='{K1}' and profile_id='{UID('dimas')}')"
expect('Kuis terkunci sebelum card selesai','dimas',f"select submit_quiz_attempt({EN},'{I2}','{{}}')",err=True)
expect('Dimas selesaikan card','dimas',f"select complete_item({EN},'{I1}'); select count(*) from item_progress",1)
expect('Rudi tidak bisa menyelesaikan item pendaftaran Dimas','rudi',f"select complete_item({EN},'{I1}')",err=True)
A_WRONG='{"e3000000-0000-0000-0000-000000000001":["e4000000-0000-0000-0000-000000000012"],"e3000000-0000-0000-0000-000000000002":["e4000000-0000-0000-0000-000000000023"]}'
A_HALF='{"e3000000-0000-0000-0000-000000000001":["e4000000-0000-0000-0000-000000000011"],"e3000000-0000-0000-0000-000000000002":["e4000000-0000-0000-0000-000000000021"]}'
A_ALL='{"e3000000-0000-0000-0000-000000000001":["e4000000-0000-0000-0000-000000000011"],"e3000000-0000-0000-0000-000000000002":["e4000000-0000-0000-0000-000000000021","e4000000-0000-0000-0000-000000000022"]}'
expect('Percobaan 1 dinilai 0 dan tidak lulus','dimas',f"select (r->>'score')||'/'||(r->>'passed')||'/'||(r->>'attempts_left') from (select submit_quiz_attempt({EN},'{I2}','{A_WRONG}') r) t",'0/false/1')
expect('Percobaan 2: jawaban separuh (jawaban ganda B tidak lengkap) 50% lulus','dimas',f"select (r->>'score')||'/'||(r->>'passed')||'/'||(r->>'escalated') from (select submit_quiz_attempt({EN},'{I2}','{A_HALF}') r) t",'50/true/false')
expect('Kursus selesai setelah semua item','dimas',f"select status from enrollments where id={EN}",'selesai')
expect('Setelah lulus tidak bisa mengulang','dimas',f"select submit_quiz_attempt({EN},'{I2}','{A_ALL}')",err=True)
expect('Dimas tidak bisa mengubah pendaftarannya sendiri','dimas',f"update enrollments set status='berjalan' where id={EN}",err=True)
print('--- 0007 batas percobaan dan eskalasi')
expect('Ayu tugaskan K1 ke Rudi','ayu',f"insert into course_assignments (course_id,holding_id,target_type,profile_id,created_by) values ('{K1}','sib','user','{UID('rudi')}','{UID('ayu')}'); select count(*) from enrollments where course_id='{K1}'",2)
ER=f"(select id from enrollments where course_id='{K1}' and profile_id='{UID('rudi')}')"
sh(db,f"select 1")
expect('Rudi selesaikan card','rudi',f"select complete_item({ER},'{I1}'); select 1",1)
expect('Rudi gagal 1','rudi',f"select (r->>'attempts_left') from (select submit_quiz_attempt({ER},'{I2}','{A_WRONG}') r) t",'1')
expect('Rudi gagal 2, eskalasi aktif','rudi',f"select (r->>'escalated')||'/'||(r->>'attempts_left') from (select submit_quiz_attempt({ER},'{I2}','{A_WRONG}') r) t",'true/0')
expect('Percobaan ke-3 ditolak','rudi',f"select submit_quiz_attempt({ER},'{I2}','{A_ALL}')",err=True)
expect('Pendaftaran Rudi ditandai eskalasi','dhaka',f"select escalated_at is not null from enrollments where id={ER}",'t')
expect('Atasan Dimas melihat pendaftarannya (Ayu bukan atasan, tapi pengelola kursus)','ayu',cnt('enrollments',f"course_id='{K1}'"),2)
expect('Dimas hanya melihat pendaftarannya sendiri','dimas',cnt('enrollments',f"course_id='{K1}'"),1)
expect('Audit mencatat eskalasi','dhaka',"select count(*)>0 from audit_log where action='course.quiz.escalate'",'t')
print('--- 0007 katalog dan daftar mandiri')
sh(db,f"insert into courses (id,title,enroll_mode,status,created_by) values ('{K2}','Terbuka','terbuka','published','{UID('ayu')}')")
sh(db,f"insert into course_holdings values ('{K2}','sib')")
sh(db,f"insert into course_access (course_id,holding_id,subject_type,unit) values ('{K2}','sib','unit','Finance')")
expect('Rudi (Finance) lihat K2 di katalog','rudi',cnt('courses',f"id='{K2}'"),1)
expect('Dimas (Operasional) tidak lihat K2','dimas',cnt('courses',f"id='{K2}'"),0)
expect('Dimas tidak bisa daftar mandiri K2','dimas',f"select self_enroll('{K2}')",err=True)
expect('Rudi daftar mandiri K2','rudi',f"select self_enroll('{K2}') is not null",'t')
expect('Daftar dua kali tidak menggandakan','rudi',f"select self_enroll('{K2}') is not null; select count(*) from enrollments where course_id='{K2}'",1)
expect('Kursus ditugaskan tidak bisa didaftar sendiri','dua',f"select self_enroll('{K1}')",err=True)
expect('Orang di luar holding tidak bisa daftar (Ayu hanya PEOPLE)','ayu',f"select self_enroll('{K2}')",err=True)
sh(db,f"update courses set status='draft' where id='{K2}'")
expect('Kursus draf tidak muncul di katalog','dua',cnt('courses',f"id='{K2}'"),0)
expect('Kursus draf tidak bisa didaftar','dua',f"select self_enroll('{K2}')",err=True)
print('--- 0007 anggota baru grup ikut terdaftar')
sh(db,"insert into groups (holding_id,name) values ('sib','Tim K3')")
